    "# ==============================================================================\n",
    "# CELL 6: ENTERPRISE VALUATION ENGINE (CATBOOST NATIVE TRAINING & SERIALIZATION)\n",
    "# ==============================================================================\n",
    "import joblib\n",
    "from catboost import CatBoostRegressor, Pool\n",
    "from sklearn.model_selection import train_test_split\n",
    "from sklearn.metrics import r2_score, mean_absolute_error, root_mean_squared_error\n",
    "\n",
    "numeric_candidates = [\"year\", \"mileage\", \"engine_capacity\", \"horsepower\", \"car_age\", \"km_per_year\"]\n",
    "categorical_candidates = [\"brand\", \"model\", \"location\", \"transmission\", \"fuel_type\", \"car_condition\", \"condition_tag\", \"trim_tier\"]\n",
    "\n",
    "num_feats = [c for c in numeric_candidates if c in df.columns]\n",
    "cat_feats = [c for c in categorical_candidates if c in df.columns]\n",
    "all_feats = num_feats + cat_feats\n",
    "\n",
    "# Ensure string types for native CatBoost handling\n",
    "for col in cat_feats:\n",
    "    df[col] = df[col].fillna(\"Missing\").astype(str)\n",
    "\n",
    "for col in num_feats:\n",
    "    df[col] = pd.to_numeric(df[col], errors=\"coerce\")\n",
    "\n",
    "X = df[all_feats].copy()\n",
    "y = df[\"log_price\"].copy()\n",
    "prices_raw = df[\"price\"].copy()\n",
    "\n",
    "# Zero-Leakage Train/Test Partition (80/20)\n",
    "X_train, X_test, y_train, y_test, p_train, p_test = train_test_split(\n",
    "    X, y, prices_raw, test_size=0.20, random_state=SEED\n",
    ")\n",
    "\n",
    "# Impute numerics using X_train medians only (Strict Anti-Leakage Rule)\n",
    "train_medians = X_train[num_feats].median().to_dict()\n",
    "X_train[num_feats] = X_train[num_feats].fillna(train_medians)\n",
    "X_test[num_feats] = X_test[num_feats].fillna(train_medians)\n",
    "\n",
    "# Build CatBoost Pools\n",
    "train_pool = Pool(X_train, y_train, cat_features=cat_feats)\n",
    "test_pool = Pool(X_test, y_test, cat_features=cat_feats)\n",
    "\n",
    "cat_model = CatBoostRegressor(\n",
    "    iterations=1000,\n",
    "    learning_rate=0.06,\n",
    "    depth=7,\n",
    "    loss_function=\"RMSE\",\n",
    "    eval_metric=\"MAE\",\n",
    "    random_seed=SEED,\n",
    "    verbose=0\n",
    ")\n",
    "\n",
    "print(\"[*] Training CatBoost Valuation Engine...\")\n",
    "cat_model.fit(train_pool, eval_set=test_pool, early_stopping_rounds=40)\n",
    "\n",
    "# Evaluation\n",
    "preds_log = cat_model.predict(test_pool)\n",
    "preds_real = np.expm1(preds_log)\n",
    "\n",
    "r2 = r2_score(y_test, preds_log)\n",
    "mae = mean_absolute_error(p_test, preds_real)\n",
    "rmse = root_mean_squared_error(p_test, preds_real)\n",
    "\n",
    "print(\"\\n\" + \"=\" * 60)\n",
    "print(f\"  R² Score (Variance Explained) : {r2 * 100:.2f}%\")\n",
    "print(f\"  Mean Absolute Error (MAE)     : {mae:,.2f} EGP\")\n",
    "print(f\"  Root Mean Squared Error       : {rmse:,.2f} EGP\")\n",
    "print(\"=\" * 60)\n",
    "\n",
    "# Production Model Wrapper\n",
    "class ApexProductionValuationEngine:\n",
    "    def __init__(self, model, num_cols, cat_cols, medians):\n",
    "        self.model = model\n",
    "        self.num_cols = num_cols\n",
    "        self.cat_cols = cat_cols\n",
    "        self.medians = medians\n",
    "\n",
    "    def predict(self, df_in):\n",
    "        eval_df = df_in.copy()\n",
    "        for c in self.num_cols:\n",
    "            eval_df[c] = pd.to_numeric(eval_df.get(c, np.nan), errors=\"coerce\").fillna(self.medians.get(c, 0))\n",
    "        for c in self.cat_cols:\n",
    "            eval_df[c] = eval_df.get(c, \"Missing\").fillna(\"Missing\").astype(str)\n",
    "        pool = Pool(eval_df[self.num_cols + self.cat_cols], cat_features=self.cat_cols)\n",
    "        return self.model.predict(pool)\n",
    "\n",
    "full_pricing_pipeline = ApexProductionValuationEngine(cat_model, num_feats, cat_feats, train_medians)\n",
    "joblib.dump(full_pricing_pipeline, \"apex_catboost_valuation.joblib\")\n",
    "print(\"[+] Valuation Artifact saved as 'apex_catboost_valuation.joblib'.\")"
