    "# ==============================================================================\n",
    "# CELL 11 (PRODUCTION TEST): MULTIMODAL VISION INFERENCE & EXTENDED SEARCH\n",
    "# ==============================================================================\n",
    "import os\n",
    "import torch\n",
    "from PIL import Image\n",
    "import matplotlib.pyplot as plt\n",
    "from IPython.display import display, HTML\n",
    "\n",
    "image_path = r\"F:\\OneDrive\\Desktop\\New folder\\car 2.jpg\"\n",
    "\n",
    "print(f\"[*] Checking image existence at: {image_path}\")\n",
    "\n",
    "if not os.path.exists(image_path):\n",
    "    print(f\"[!] Error: File not found at '{image_path}'. Check if file name or drive letter differs.\")\n",
    "else:\n",
    "    # 1. عرض الصورة\n",
    "    img = Image.open(image_path).convert(\"RGB\")\n",
    "    plt.figure(figsize=(6, 4))\n",
    "    plt.imshow(img)\n",
    "    plt.axis(\"off\")\n",
    "    plt.title(\"Query Vehicle Image\", fontsize=12)\n",
    "    plt.show()\n",
    "\n",
    "    # 2. استنتاج نوع وموديل العربية من موديل الرؤية الحاسوبية\n",
    "    predicted_label = classify_car_image(image_path)\n",
    "    print(f\"🔍 [Vision Engine Detection Result]: '{predicted_label}'\")\n",
    "\n",
    "    # 3. تشغيل البحث الهجين المعتمد على مخرجات الصورة + شروط المستخدم\n",
    "    print(\"\\n\" + \"=\" * 80)\n",
    "    print(\"      RUNNING MULTIMODAL SEARCH: VISION + USER PREFERENCES       \")\n",
    "    print(\"=\" * 80)\n",
    "\n",
    "    # دمج الماركة/الموديل المستخرجين مع الشروط\n",
    "    if predicted_label:\n",
    "        combined_query = f\"{predicted_label} فابريكا وسعر معقول\".strip()\n",
    "    else:\n",
    "        combined_query = \"فابريكا وسعر معقول\"\n",
    "\n",
    "    print(f\"[*] Executing Search for: '{combined_query}'\")\n",
    "\n",
    "    # عرض حتى 8 إعلانات حية (أو ضعي top_k=None لعرض كل الإعلانات المتاحة)\n",
    "    render_user_search_results(\n",
    "        query=combined_query,\n",
    "        top_k=8\n",
    "    )"
